if false
    stop_eps = 1e-6
    stop_t = 1e9
    stop_iters=10000

    # warm up
    nash(ntuple(_ -> zeros(2, 2), 2); stop_eps, stop_t, stop_iters)
    nash(ntuple(_ -> zeros(2, 2, 2), 3); stop_eps, stop_t, stop_iters)
    nash(ntuple(_ -> zeros(2, 2, 2, 2), 4); stop_eps, stop_t, stop_iters)
    equilibrium_gap(ntuple(_ -> zeros(2, 2), 2), ntuple(_->zeros(2), 2))
    equilibrium_gap(ntuple(_ -> zeros(2, 2, 2), 3), ntuple(_->zeros(2), 3))
    equilibrium_gap(ntuple(_ -> zeros(2, 2, 2, 2), 4), ntuple(_->zeros(2), 4))

    # run
    for set in (set_rn22, set_rn33, set_rn44, set_rn222, set_rn2222, set_tst)
        println()
        @time begin
            for game in set

                xs, status = nash(game; stop_eps, stop_t, stop_iters)
                actual_gap = equilibrium_gap(game, xs)

                if actual_gap > stop_eps || status.stall || status.t < 0
                    #  @warn "gap, $actual_gap (< $stop_eps), $status"
                    print("X")
                else
                    print(".")
                end
            end
            println()
        end
    end
    println()
end

